begin;
do $test$
#variable_conflict use_variable
declare owner_id uuid=gen_random_uuid(); buyer uuid=gen_random_uuid(); sid uuid=gen_random_uuid(); bsid uuid=gen_random_uuid(); item uuid=gen_random_uuid(); plain uuid=gen_random_uuid(); moderated uuid=gen_random_uuid(); active_item uuid=gen_random_uuid(); chat uuid=gen_random_uuid(); report uuid=gen_random_uuid(); got jsonb; n integer; photo text;
begin
 insert into auth.users(id,email_confirmed_at,raw_user_meta_data) values(owner_id,now(),'{"display_name":"Deletion rollback owner"}'),(buyer,now(),'{"display_name":"Deletion rollback buyer"}');
 insert into auth.sessions(id,user_id) values(sid,owner_id),(bsid,buyer);
 photo=owner_id::text||'/'||item::text||'-test.jpg';
 insert into public.listing_assets(path,owner_id) values(photo,owner_id),(owner_id::text||'/'||plain::text||'-test.jpg',owner_id),(owner_id::text||'/'||moderated::text||'-test.jpg',owner_id),(owner_id::text||'/'||active_item::text||'-test.jpg',owner_id);
 insert into public.listings(id,owner_id,title,description,price,category,condition,province,area,image_path,status,moderation_removed)
 select v.id,owner_id,v.title,'Original description',100,'Other Items','Good','National Capital District','Test',owner_id::text||'/'||v.id::text||'-test.jpg','available',v.flag from (values(item,'Reported original',false),(plain,'Unreported',false),(moderated,'Moderated',true),(active_item,'Active',false))v(id,title,flag);
 insert into public.chat_conversations(id,listing_id,buyer_id) values(chat,item,buyer);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',bsid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 insert into public.listing_reports(reporter_id,listing_id,reason,details) values(buyer,item,'Other','Rollback-only evidence') returning id into report;
 execute 'reset role';
 update public.listings set status='removed' where id in(item,plain,moderated);
 insert into public.chat_messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),chat,buyer,'Preserved rollback chat');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',bsid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if not exists(select 1 from public.chat_inbox where id=chat and listing_title='Listing no longer available') then raise exception 'Soft-removed listing mislabeled as deleted';end if;
 begin perform public.begin_listing_deletion(item);raise exception 'Other owner was permitted';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',sid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.begin_listing_deletion(moderated);raise exception 'Moderated listing was permitted';exception when raise_exception then if sqlerrm='Moderated listing was permitted' then raise;end if;end;
 begin perform public.begin_listing_deletion(active_item);raise exception 'Active listing was permitted';exception when raise_exception then if sqlerrm='Active listing was permitted' then raise;end if;end;
 got=public.begin_listing_deletion(item);
 if not(got->>'retained_evidence')::boolean then raise exception 'Missing evidence retention';end if;
 if not exists(select 1 from public.listings where id=item and deletion_cleanup_pending and image_path is null and title='Listing deleted') then raise exception 'Retry tombstone missing';end if;
 execute 'reset role';
 if (select evidence->>'title' from private.listing_deletions where listing_id=item)<>'Reported original' then raise exception 'Evidence erased';end if;
 if not exists(select 1 from public.chat_messages where conversation_id=chat) or not exists(select 1 from public.listing_reports where id=report) then raise exception 'Chat or report lost';end if;
 perform public.finish_listing_deletion(item,owner_id);
 if not exists(select 1 from public.listing_assets where path=photo) then raise exception 'Evidence asset removed';end if;
 execute 'set local role authenticated';
 if exists(select 1 from public.listings where id=item) then raise exception 'Completed listing remains visible';end if;
 got=public.begin_listing_deletion(item);
 if not(got->>'completed')::boolean then raise exception 'Retry not idempotent';end if;
 update public.listings set status='available' where id=item;
 get diagnostics n=row_count;
 if n<>0 then raise exception 'Deleted listing reactivated';end if;
 got=public.begin_listing_deletion(plain);
 if (got->>'retained_evidence')::boolean then raise exception 'Unreported evidence retained';end if;
 execute 'reset role';
 perform public.finish_listing_deletion(plain,owner_id);
 if exists(select 1 from public.listing_assets where path like owner_id::text||'/'||plain::text||'-%') then raise exception 'Unreported asset metadata retained';end if;
 insert into private.moderator_accounts(user_id,granted_reason) values(buyer,'Rollback-only moderator');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'session_id',bsid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 got=public.moderation_report('listing',report);
 if got->'listing'->>'title'<>'Reported original' or got->'listing'->>'image_path'<>photo then raise exception 'Moderator evidence missing';end if;
 if not private.moderator_reported_photo(photo) then raise exception 'Moderator photo access lost';end if;
 if not exists(select 1 from public.chat_inbox where id=chat and listing_title='Listing deleted') then raise exception 'Deleted chat label missing';end if;
 execute 'reset role';
 if has_function_privilege('authenticated','public.finish_listing_deletion(uuid,uuid)','execute') or has_function_privilege('anon','public.begin_listing_deletion(uuid)','execute') or has_column_privilege('authenticated','public.listings','permanently_deleted_at','insert') then raise exception 'Excess privilege';end if;
 delete from auth.sessions where id=sid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',sid,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.begin_listing_deletion(active_item);raise exception 'Revoked session permitted';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $test$;
select 'Ownership, removed-only, moderator exclusion, evidence, chat history, hidden completion, retry, privilege and revoked-session checks passed; fixtures rolled back.' as verification;
rollback;